def fill_if_anchored(I,O,col):
    I=I.copy(); H,W=I.shape; out=O.copy()
    for r in range(H):
        cs=[c for c in range(W) if I[r,c]==col]
        for a,b in zip(cs,cs[1:]):
            if b-a-1>=1:
                v_a=any(I[rr][a]==col for rr in range(H) if rr!=r)
                h_a=any(I[r][cc]==col for cc in range(W) if cc!=a)
                v_b=any(I[rr][b]==col for rr in range(H) if rr!=r)
                h_b=any(I[r][cc]==col for cc in range(W) if cc!=b)
                if (v_a or h_a) and (v_b or h_b):
                    out[r,a+1:b]=2
    return out
