# maybe rule is: fill gap only if it lies BETWEEN two markers that are themselves endpoints of OTHER filled segments / or the gap has length equal to something like min distance? 
# Or the pattern: gaps get filled unless the gap's length equals the distance from marker to grid edge?
# check demo1 row6: gap 0..13, length 12, fills none. But col0 has many markers so gap(8,11) got filled! yet gap 12 didn't. Hmm gap(8,11) length 2 filled; col9 gap length 9 unfilled. So threshold somewhere between 2 and 9 but d2 fills up to 6.
def fmax(g,m):
    g=np.array(g); res=g.copy(); H,W=g.shape; bg=g[0][0]
    for r in range(H):
        cs=[c for c in range(W) if g[r,c]!=bg]
        for a,b in zip(cs,cs[1:]):
            if b-a-1>=1 and b-a-1<=m: res[r,a+1:b]=2
    for c in range(W):
        rs=[r for r in range(H) if g[r,c]!=bg]
        for a,b in zip(rs,rs[1:]):
            if b-a-1>=1 and b-a-1<=m: res[a+1:b,c]=2
    return res.tolist()
