# Line lengths per cell for marker color
def lens(I):
    I=np.array(I); H,W=I.shape
    cnt=collections.Counter(I.flatten().tolist()); mc=min(cnt,key=lambda k:(cnt[k],k))
    # horizontal line length containing each marker cell
    hl=[0]*H; vl=[0]*W
    for r in range(H):
        cs=[c for c in range(W) if I[r,c]==mc]
        for a,b in zip(cs,cs[1:]):
            for c in range(a,b+1): hl[r]+=0
    # compute line spans
    Lr=[]; Lc=[]
    for r in range(H):
        cs=[c for c in range(W) if I[r,c]==mc]
        for a,b in zip(cs,cs[1:]):
            Lr.append(('h',r,a,b))
    for c in range(W):
        rs=[r for r in range(H) if I[r,c]==mc]
        for a,b in zip(rs,rs[1:]):
            Lc.append(('v',c,a,b))
    return mc,Lr,Lc
def solve_grid(I,verbose=False):
    mc,Lr,Lc=lens(I)
    H,W=I.shape; out=I.copy()
    def llen(spans,line):
        # length of line span covering cell
        s=next((s for s in spans if s[1]<=line<=s[3]),None)
        return (s[2]-s[1]+1) if s else None
    for ('h',r,a,b) in Lr:
        g=b-a-1
        la=llen(Lr,spans=Lr+[s for s in Lc if False]); 
        ll_a=len(next(s for s in Lr if s[1]<=a<=s[3]))
        ll_b=len(next(s for s in Lr if s[1]<=b<=s[3]))
        vv_a=max(len(s) for s in Lr if s[1]<=a<=s[3]) if False else None
        # simpler: horizontal span through a/b, vertical span through a/b
        ha=len([c for c in range(W) if I[r,c]==mc and (a-1<=c<=a)] or [])
        # just: line length through a in horizontal direction
        hsa=[s for s in Lr if s[0]=='h' and s[1]<=a<=s[3]][0]
        hs b=[s for s in Lr if s[0]=='h' and s[1]<=b<=s[3]][0]
        va=[s for s in Lc if s[0]=='v' and s[1]<=a<=s[3]][0]
        vb=[s for s in Lc if s[0]=='v' and s[1]<=b<=s[3]][0]
        ok = (hsa==('h',r,0,a)) or (hsb==('h',r,b,b)) or (va[3]-va[1]+1==1) or (vb[3]-vb[1]+1==1)
        if ok:
            out[r,a:b]=2
    return out.tolist(),mc,len(Lr),len(Lc)
