def f(I, fill=2):
    I=np.array(I); H,W=I.shape
    cnt=collections.Counter(I.flatten()); mc=min(cnt,key=lambda k:(cnt[k],k))
    out=I.copy()
    def prun(c): return int(np.sum(I[:,c]==mc))
    def ptrun(r): return int(np.sum(I[r,:]==mc))
    # horizontal
    for r in range(H):
        cs=[c for c in range(W) if I[r,c]==mc]
        for a,b in zip(cs,cs[1:]):
            g=b-a-1
            if g>=5 and prun(a)>=5 and prun(b)>=5: continue
            out[r,a+1:b]=fill
    # vertical
    for c in range(W):
        rs=[r for r in range(H) if I[r,c]==mc]
        for a,b in zip(rs,rs[1:]):
            g=b-a-1
            if g>=5 and ptrun(a)>=5 and ptrun(b)>=5: continue
            out[a+1:b,c]=fill
    return out.tolist()

