def gaps_of(I,O,name,axis):
    res=[]
    I=np.array(I); O=np.array(O); H,W=I.shape
    cnt=collections.Counter(I.flatten()); mc=min(cnt,key=lambda k:(cnt[k],k))
    def runs(cells):
        rs=[];s=None
        for c in cells+[None]:
            if s is None:
                if c is None: break
                if I[c]==mc: s=c
            else:
                if I[c]==mc: pass
                else:
                    rs.append((s,c-1)); s=None
                if c>=W: rs.append((s,H-1))
        return [(a,b) for a,b in rs]
    def pfill(I,O,a,b,axis_):
        if axis_: 
            ok = (O[a+1:b,c]==2).all()
            la = int(sum(1 for cc in range(max(0,a-1),a) if I[r_,cc]==mc))
        else:
            ok = (O[r_,a+1:b]==2).all()
            la = int(sum(1 for r_ in range(max(0,a-1),a) if I[r_,c]==mc))
        return ok, la
    for r in range(H):
        cs=[c for c in range(W) if I[r,c]==mc]
        pairs=list(zip(cs,cs[1:]))
        for aa,bb in pairs:
            g=bb-aa-1
            ok,la=pfill(I,O,aa,bb,None)
            lb=int(sum(1 for c2 in range(bb+1,min(W,bb+2)) if I[r,c2]==mc))
            res.append(('h',g,int(ok),int(la),int(la or 0),lb))
    # vertical
    for c in range(W):
        rs=[r for r in range(H) if I[r,c]==mc]
        pairs=list(zip(rs,rs[1:]))
        for aa,bb in pairs:
            g=bb-aa-1
            ok=(O[aa+1:bb,c]==2).all()
            ua=int(sum(1 for r_ in range(max(0,aa-1),aa) if I[r_,c]==mc))
            ub=int(sum(1 for r_ in range(bb+1,min(H,bb+2)) if I[r_,c]==mc))
            res.append(('v',g,int(ok),ua,ub))
    return res
